oxy_webhelp_navlinks = {"mv_manage_snapshots-d39307e49476":{"topics":[{"title":"Managed Volumes and SLA Managed Volumes object details","shortdesc":"<p class=\"shortdesc\">The Managed Volumes object details page provides an Overview page, a Snapshots page,         and an Events page for each Managed Volume and SLA Managed Volume.<\/p>","href":"managedvolumes\/mv_managed_volume_object_details.html","attributes":{"data-id":"mv_managed_volume_object_details"},"menu":{"hasChildren":false},"tocID":"mv_managed_volume_object_details-d39307e49487","next":"mv_managed_volume_object_details-d39307e49487"},{"title":"Managed Volumes and SLA Managed Volumes snapshot management","shortdesc":"<p class=\"shortdesc\">The SLA Domain assigned to a Managed Volume or SLA Managed Volume controls snapshot         frequency, retention, archiving, and replication.<\/p>","href":"managedvolumes\/mv_managed_volume_snapshot_management.html","attributes":{"data-id":"mv_managed_volume_snapshot_management"},"menu":{"hasChildren":false},"tocID":"mv_managed_volume_snapshot_management-d39307e49531","next":"mv_managed_volume_snapshot_management-d39307e49531"},{"title":"Object-level pause and resume for Managed Volumes and SLA Managed Volumes","shortdesc":"<p class=\"shortdesc\">You can temporarily pause and resume protection for individual Managed Volumes or SLA         Managed Volumes without affecting the protection of other objects managed by the same SLA         Domain.<\/p>","href":"managedvolumes\/mv_obj_level_pause_resume.html","attributes":{"data-id":"mv_obj_level_pause_resume"},"menu":{"hasChildren":false},"tocID":"mv_obj_level_pause_resume-d39307e49597","topics":[]},{"title":"Managed Volumes and SLA Managed Volumes reset reasons","shortdesc":"<p class=\"shortdesc\">When a Managed Volume or SLA Managed Volume encounters a condition that requires         intervention, <span class=\"ph\">RSC<\/span> displays the reset reason on the Managed Volumes and SLA Managed Volumes pages so         you can identify the cause and take the appropriate action.<\/p>","href":"managedvolumes\/mv_reset_reasons.html","attributes":{"data-id":"mv_reset_reasons"},"menu":{"hasChildren":false},"tocID":"mv_reset_reasons-d39307e49608","topics":[]}]}};